def tag_configurada(padrao=''):
    """Validation stage: Clickadilla only, same tag on every device."""
    return VAST_TAG_PADRAO

def _media_escolhido(inline, altura_tela=0):
    """Arquivo do anuncio que o player do Kodi consegue tocar.

    Preferencia: MP4/WebM progressivo (o Kodi abre direto por URL), do maior
    para o menor. HLS (``application/x-mpegURL``) entra como segunda opcao -
    o Kodi 21 toca HLS, mas em box/stick antigo o MP4 e mais confiavel.
    """
    candidatos = []
    for linear in inline.iter('Linear'):
        for media in linear.iter('MediaFile'):
            url = (media.text or '').strip()
            if not url.startswith(('<redacted-network-or-token-literal>', '<redacted-network-or-token-literal>')):
                continue
            tipo = (media.get('type') or '').lower()
            largura = _inteiro(media.get('width'))
            altura = _inteiro(media.get('height'))
            url_limpa = url.lower().split('?', 1)[0]
            mp4 = tipo.startswith(('video/mp4', 'video/x-m4v')) or (not tipo and url_limpa.endswith(('.mp4', '.m4v')))
            progressivo = mp4 or tipo.startswith('video/webm')
            hls = 'mpegurl' in tipo or url_limpa.endswith('.m3u8')
            if not (progressivo or hls):
                continue
            candidatos.append({'url': url, 'tipo': tipo, 'largura': largura, 'altura': altura, 'prioridade': 0 if mp4 else 1 if progressivo else 2, 'progressivo': progressivo, 'proximidade': abs((altura or 0) - (altura_tela or 1080))})
    if not candidatos:
        return None
    candidatos.sort(key=lambda item: (item['prioridade'], item['proximidade'], -item['altura'], -item['largura']))
    return candidatos[0]

def tag_do_wrapper(xml):
    """URL que um ``<Wrapper>`` manda seguir ('' quando nao e wrapper)."""
    if not xml:
        return ''
    xml = sem_namespace(xml)
    try:
        import xml.etree.ElementTree as ET
        raiz = ET.fromstring(xml.strip())
    except Exception:
        return ''
    for anuncio in raiz.iter('Ad'):
        wrapper = anuncio.find('Wrapper')
        if wrapper is None:
            continue
        for alvo in wrapper.iter('VASTAdTagURI'):
            valor = (alvo.text or '').strip()
            if valor.startswith(('<redacted-network-or-token-literal>', '<redacted-network-or-token-literal>')):
                return valor
    return ''

def tag_do_vmap(xml):
    """URL do primeiro ``<AdBreak>`` de um VMAP ('' quando nao e VMAP).

    O Ad Manager entrega playlist de anuncios em VMAP por padrao. O criativo
    continua sendo VAST: a URL de cada AdBreak aponta para a tag VAST daquele
    intervalo. Sem este passo um VMAP era descartado como "sem criativo".
    """
    if not xml:
        return ''
    xml = sem_namespace(xml)
    try:
        import xml.etree.ElementTree as ET
        raiz = ET.fromstring(xml.strip())
    except Exception:
        return ''
    if 'VMAP' not in (raiz.tag.split('}')[-1] or ''):
        return ''
    for alvo in raiz.iter():
        if alvo.tag.split('}')[-1] != 'AdTagURI':
            continue
        valor = (alvo.text or '').strip()
        if valor.startswith(('<redacted-network-or-token-literal>', '<redacted-network-or-token-literal>')):
            return valor
    return ''

def escolher_anuncio(xml, altura_tela=0):
    """Le o VAST e devolve o anuncio a tocar (dict) ou ``None``.

    Aceita o XML como texto ou bytes. Um VAST de ``Wrapper`` (que aponta para
    outra tag) NAO vira anuncio aqui: quem chama precisa seguir a tag (ver
    ``exibir``, que segue ate ``PROFUNDIDADE_WRAPPER`` niveis).
    """
    try:
        import xml.etree.ElementTree as ET
    except Exception:
        return None
    if not xml:
        return None
    xml = sem_namespace(xml)
    try:
        raiz = ET.fromstring(xml.strip())
    except Exception:
        return None
    for anuncio in raiz.iter('Ad'):
        inline = anuncio.find('InLine')
        if inline is None:
            continue
        linear = inline.find('.//Linear')
        if linear is None:
            continue
        media = _media_escolhido(inline, altura_tela)
        if not media:
            continue
        criativo = inline.find('Creatives/Creative')
        try:
            identificador = (criativo.get('id') if criativo is not None else '') or ''
        except Exception:
            identificador = ''
        eventos = {}
        for nome, _quarto in QUARTIS:
            eventos[nome] = _urls_de_evento(linear, nome)
        eventos['skip'] = _urls_de_evento(linear, 'skip')
        return {'url': media['url'], 'tipo': media['tipo'], 'duracao': _duracao(linear), 'tempo_skip': _segundos(linear.get('skipoffset')), 'impressao': _urls_de_impressao(inline), 'eventos': eventos, 'id': identificador, 'errors': [valor.strip() for valor in [e.text or '' for e in inline.iter('Error')] if valor.strip().startswith(('http', '//'))]}
    return None

def baixar(url, timeout=TIMEOUT_HTTP):
    """Verified TLS 1.2+, Chrome Android headers, bounded response/time."""
    if not url:
        return None
    try:
        import ssl
        import time as _clock
        from urllib.request import Request, urlopen
        context = ssl.create_default_context()
        context.minimum_version = ssl.TLSVersion.TLSv1_2
        budget = min(max(float(timeout), 0.1), 8.0)
        deadline = _clock.monotonic() + budget
        request = Request(url, headers={'User-Agent': 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36', 'Accept': 'application/xml,text/xml,*/*;q=0.8', 'Accept-Language': 'pt-BR,pt;q=0.9,en;q=0.8', 'Accept-Encoding': 'identity'})
        with urlopen(request, timeout=budget, context=context) as response:
            chunks = []
            size = 0
            while True:
                if _clock.monotonic() >= deadline:
                    return None
                chunk = response.read(65536)
                if not chunk:
                    return b''.join(chunks)
                size += len(chunk)
                if size > 2 * 1024 * 1024:
                    return None
                chunks.append(chunk)
    except Exception:
        return None

def exibir(log=None, tag='', altura_tela=0, tempo_maximo=TEMPO_MAXIMO_ANUNCIO, baixar_tag=None, tocar=None, dormir=None):
    """Caminho completo: tag -> VAST -> player. Devolve recibo (dict).

    Qualquer falha (sem tag, rede, VAST invalido, player recusando) devolve
    ``{'exibido': False, 'motivo': ...}`` - e quem chamou libera o conteudo.
    """
    if not tag:
        return {'exibido': False, 'motivo': 'sem-tag'}
    baixar_tag = baixar_tag or baixar
    try:
        dados = baixar_tag(tag)
    except Exception as erro:
        if log:
            log('[SmartAds] VAST: falha ao consultar tag (%s)' % erro, xbmc.LOGWARNING)
        return {'exibido': False, 'motivo': 'tag-sem-resposta'}
    if not dados:
        if log:
            log('[SmartAds] VAST: a tag nao respondeu', xbmc.LOGWARNING)
        return {'exibido': False, 'motivo': 'tag-sem-resposta'}
    anuncio = escolher_anuncio(dados, altura_tela)
    nivel = 0
    while not anuncio and nivel < PROFUNDIDADE_WRAPPER:
        e_wrapper = bool(tag_do_wrapper(dados))
        alvo = tag_do_wrapper(dados) or tag_do_vmap(dados)
        if not alvo:
            break
        nivel += 1
        if log:
            log('[SmartAds] VAST: seguindo %s (nivel %d)' % ('wrapper' if e_wrapper else 'VMAP - AdBreak do Ad Manager', nivel))
        try:
            dados = baixar_tag(alvo)
        except Exception:
            dados = None
        if not dados:
            break
        anuncio = escolher_anuncio(dados, altura_tela)
    if not anuncio:
        if log:
            log('[SmartAds] VAST: resposta sem criativo de video linear', xbmc.LOGWARNING)
        return {'exibido': False, 'motivo': 'vast-sem-criativo'}
    recibo = reproduzir(anuncio, log=log, tempo_maximo=tempo_maximo, tocar=tocar, dormir=dormir)
    recibo['anuncio'] = anuncio.get('id') or anuncio.get('url')
    return recibo

