        if log:
            log('[SmartAdsDiag] regra=uma-tentativa-por-abertura; sem-cooldown')
        return bool(result)

class MonitorPreRoll(_BasePlayer):
    """Escuta o inicio de QUALQUER stream e chama o pre-roll.

    Vale para canal de TV, filme e serie, venha do Brazuca ou de outro addon:
    o gancho e o proprio xbmc.Player, nao a rota do addon.

    Regra: cada inicio de reproducao e um candidato a anuncio, mas quem decide
    e ``ads_regra`` — troca de conteudo + intervalo de 2 minutos desde o ultimo
    anuncio exibido. O par ``onPlayBackStarted``/``onAVStarted`` do MESMO inicio
    conta como um so, e a volta do anuncio nunca pede outro.
    """

    def __init__(self, log=None, intervalo=None):
        if _BasePlayer is not object:
            _BasePlayer.__init__(self)
        self.log = log
        self.intervalo = intervalo
        self.ultimo_caminho = None
        self.sessao = 0
        self.retomada = None
        self._em_vast = False
        self._ate_ignorar_volta_vast = 0.0
        self._volta_vast_chave = ''
        self._vast_lock = threading.Lock()

    def _retomada(self):
        if self.retomada is None:
            try:
                from ad_return import Retomada
                self.retomada = Retomada(self.log)
            except Exception:
                self.retomada = False
        return self.retomada

    def _garantir_player_tela_cheia(self):
        try:
            if _e_video(self) and (not xbmc.getCondVisibility('Window.IsActive(fullscreenvideo)')):
                xbmc.executebuiltin('ActivateWindow(fullscreenvideo)')
        except Exception:
            pass

    def _ciclo_vast(self, atividade, log, caminho_inicial=''):
        from ads_openings import state, context, emit
        ledger = state(self)
        generation = ledger.generation
        context(generation)
        success = False
        changed = False
        receipt = {}
        with self._vast_lock:
            self._em_vast = True
            try:
                with _LOCK_OPORTUNIDADE:
                    key = _chave_conteudo(caminho_inicial)
                globals()['_smarted_last_receipt'] = {}
                success = bool(abrir_anuncio(atividade, log))
                receipt = globals().get('_smarted_last_receipt') or {}
                changed = receipt.get('motivo') == 'conteudo-alterado'
                with _LOCK_OPORTUNIDADE:
                    if success:
                        ads_regra.registrar_anuncio(key, time.time())
                        ads_regra.concluir_anuncio(time.time())
                    else:
                        ads_regra.cancelar_anuncio(key)
            except Exception as exc:
                with _LOCK_OPORTUNIDADE:
                    ads_regra.cancelar_anuncio(caminho_inicial)
                emit(xbmc, 'cycle-failed-open', error=type(exc).__name__)
            finally:
                returned = self._caminho() or caminho_inicial
                returned_key = _normalizar_caminho_chave(returned)
                no_media_attempt = not receipt.get('url_anuncio') and (not receipt.get('precisa_restaurar')) and ('retomada_confirmada' not in receipt)
                same_channel = bool(ledger.channel and xbmc.getInfoLabel('VideoPlayer.ChannelName') == ledger.channel)
                if not success and no_media_attempt and returned_key and (returned_key not in ledger.aliases) and (not same_channel):
                    changed = True
                    emit(xbmc, 'content-changed-during-attempt')
                ledger.finish(generation, '' if changed else _normalizar_caminho_chave(returned))
                self._em_vast = False
                emit(xbmc, 'cycle-finished', ad_and_resume_confirmed=success)
            if not changed:
                self._garantir_player_tela_cheia()
                if returned:
                    self._vigiar_imagem(returned)
        if changed:
            ledger.close()
            self._talvez_mostrar()
        return success

    def _smarted_disparar_original(self, atividade, log):
        if usar_vast():
            caminho_atual = self._caminho() or self.ultimo_caminho or ''
            if android():
                if self._em_vast:
                    return False
                self._em_vast = True
                threading.Thread(target=self._ciclo_vast, args=(atividade, log, caminho_atual), name='smarted-vast-preroll', daemon=True).start()
                return True
            return self._ciclo_vast(atividade, log, caminho_atual)
        retomada = self._retomada()
        if retomada:
            try:
                retomada.armar(self)
            except Exception as erro:
                if log:
                    log('[SmartAds] ponto de retomada falhou (%s)' % type(erro).__name__)
        disparou = abrir_anuncio(atividade, log)
        if not disparou:
            if retomada:
                retomada.cancelar()
            return False
        if retomada:
            estado = retomada.guardado()
            if estado:
                threading.Thread(target=retomada.vigiar, args=(self, estado), name='volta-anuncio', daemon=True).start()
        return True

    def _disparar(self, atividade, log):
        if not usar_vast():
            return self._smarted_disparar_original(atividade, log)
        if self._em_vast:
            return False
        path = self._caminho() or self.ultimo_caminho or ''
        self._em_vast = True
        try:
            threading.Thread(target=self._ciclo_vast, args=(atividade, log, path), name='smarted-vast-preroll', daemon=True).start()
        except Exception:
            self._em_vast = False
            if log:
                log('[SmartAdsDiag] falha-agendamento-vast')
        return False

    def _caminho(self):
        try:
            caminho = xbmc.Player().getPlayingFile()
        except Exception:
            caminho = None
        if not caminho:
            for rotulo in ('Player.FilenameAndPath', 'Player.Url'):
                try:
                    caminho = xbmc.getInfoLabel(rotulo) or ''
                except Exception:
                    caminho = ''
                if caminho:
                    break
        return caminho or None

    def _smarted_talvez_mostrar_original(self):
        if self._em_vast:
            return
        try:
            if not _e_video(self):
                return
            caminho = self._caminho() or self.ultimo_caminho
            if self._ate_ignorar_volta_vast and time.monotonic() < self._ate_ignorar_volta_vast:
                base_atual = _normalizar_caminho_chave(caminho)
                if not self._volta_vast_chave or not base_atual or base_atual == self._volta_vast_chave:
                    if not self._volta_vast_chave:
                        self._ate_ignorar_volta_vast = 0.0
                    globals()['_ultima_sessao'] = self.sessao
                    self._garantir_player_tela_cheia()
                    try:
                        ads_regra.concluir_anuncio()
                    except Exception:
                        pass
                    if self.log:
                        self.log('[SmartAds] volta do anuncio VAST: tela cheia restaurada')
                    return
                self._ate_ignorar_volta_vast = 0.0
                self._volta_vast_chave = ''
            retomada = self._retomada()
            canal = xbmc.getInfoLabel('VideoPlayer.ChannelName') or ''
            if retomada and retomada.e_volta(caminho, canal):
                globals()['_ultima_sessao'] = self.sessao
                self._garantir_player_tela_cheia()
                try:
                    ads_regra.concluir_anuncio()
                except Exception:
                    pass
                self._vigiar_imagem(caminho)
                if self.log:
                    self.log('[SmartAds] volta do anuncio: sem novo pre-roll')
                return
            chave = _chave_conteudo(caminho)
            self.ultimo_caminho = caminho
            disparou = mostrar_preroll(self.log, self.intervalo, caminho=caminho, chave=chave, sessao=self.sessao, disparar=self._disparar)
            if not disparou:
                self._vigiar_imagem(caminho)
        except Exception as erro:
            if self.log:
                self.log('[SmartAds] pre-roll falhou (%s)' % erro, xbmc.LOGWARNING)

    def _talvez_mostrar(self):
        from ads_openings import blocked, emit
        if not usar_vast():
            emit(xbmc, 'native-admob-eligibility-delegated')
            return self._smarted_talvez_mostrar_original()
        from ads_openings import state, context, emit, blocked, reset_boundary
        if self._em_vast:
            blocked(self, xbmc, 'ad-cycle-running')
            return 'blocked'
        if not _e_video(self):
            blocked(self, xbmc, 'video-not-ready')
            return 'pending'
        path = self._caminho()
        if not path:
            blocked(self, xbmc, 'path-not-ready')
            return 'pending'
        if vip_ativo():
            blocked(self, xbmc, 'vip-exempt')
            return 'blocked'
        if getattr(self, '_smarted_gate_path', None) != path:
            self._smarted_gate_path = path
            emit(xbmc, 'eligibility-ready')
        ledger = state(self)
        channel = xbmc.getInfoLabel('VideoPlayer.ChannelName') or ''
        generation = ledger.claim(_normalizar_caminho_chave(path), channel)
        if generation is None:
            blocked(self, xbmc, 'ad-cycle-running' if ledger.in_ad else 'opening-already-attempted')
            return 'blocked'
        self._smarted_last_block = None
        reset_boundary(self, xbmc, 'opening-accepted')
        context(generation)
        emit(xbmc, 'opening-claimed')
        self.sessao = generation
        self.ultimo_caminho = path
        self._ate_ignorar_volta_vast = 0.0
        self._volta_vast_chave = ''
        try:
            with _LOCK_OPORTUNIDADE:
                esquecer()
                mostrar_preroll(self.log, self.intervalo, caminho=path, chave=_chave_conteudo(path), sessao=generation, disparar=self._disparar)
        except Exception as exc:
            emit(xbmc, 'opening-failed-open', error=type(exc).__name__)
        finally:
            if not self._em_vast:
                ledger.finish(generation, _normalizar_caminho_chave(path))
        return 'accepted'

    def _vigiar_imagem(self, caminho):
        """So para canal continuo, e sem tocar em filme/serie."""
        try:
            import ao_vivo
        except Exception:
            return None
        try:
            if not ao_vivo.eh_ao_vivo(caminho):
                return None
        except Exception:
            return None
        return ao_vivo.iniciar(self, caminho, self.log)

    def onPlayBackStarted(self):
        if self._em_vast:
            return
        self.sessao += 1

    def onAVStarted(self):
        if self._em_vast:
            return
        self._talvez_mostrar()

    def onPlay(self, **kwargs):
        if self._em_vast:
            return
        self._talvez_mostrar()

    def _smarted_stop_original(self):
        if self._em_vast or _e_video(self):
            return
        self._ate_ignorar_volta_vast = 0.0
        self._volta_vast_chave = ''
        self._limpar_retomada()
        self.ultimo_caminho = None
        self.sessao += 1
        esquecer()

    def onPlayBackStopped(self):
        if not usar_vast():
            return self._smarted_stop_original()
        from ads_openings import state, emit
        if self._em_vast or not state(self).close():
            return
        self._ate_ignorar_volta_vast = 0.0
        self._volta_vast_chave = ''
        self._smarted_gate_path = None
        self._smarted_stopped_path = self._caminho() or self.ultimo_caminho or ''
        self._smarted_wait_for_video_boundary = True
        self._limpar_retomada()
        emit(xbmc, 'opening-closed', boundary='stop')

    def _smarted_end_original(self):
        if self._em_vast:
            return
        retomada = self._retomada()
        if retomada and retomada.guardado():
            return
        if self._ate_ignorar_volta_vast and time.monotonic() < self._ate_ignorar_volta_vast:
            return
        try:
            import ao_vivo
            if self.ultimo_caminho and ao_vivo.eh_ao_vivo(self.ultimo_caminho):
                return
        except Exception:
            pass
        self._limpar_retomada()

    def onPlayBackEnded(self):
        if not usar_vast():
            return self._smarted_end_original()
        from ads_openings import state, emit
        if self._em_vast:
            return
        try:
            import ao_vivo
            if self.ultimo_caminho and ao_vivo.eh_ao_vivo(self.ultimo_caminho):
                return
        except Exception:
            pass
        if state(self).close():
            self._ate_ignorar_volta_vast = 0.0
            self._volta_vast_chave = ''
            self._smarted_gate_path = None
            self._smarted_stopped_path = self._caminho() or self.ultimo_caminho or ''
            self._smarted_wait_for_video_boundary = True
            self._limpar_retomada()
            emit(xbmc, 'opening-closed', boundary='end')

    def _limpar_retomada(self):
        retomada = self._retomada()
        if retomada:
            retomada.cancelar()
        self.ultimo_caminho = None
        self.sessao += 1
        esquecer()

